    # Solid lines divide the grid into panels.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    rb = [-1] + sep_rows + [h]
    cb = [-1] + sep_cols + [w]
    bands = [(rb[i] + 1, rb[i + 1]) for i in range(len(rb) - 1)]
    panels = [(cb[i] + 1, cb[i + 1]) for i in range(len(cb) - 1)]

    # The background is the most common color, excluding separator lines.
    excluded = set(sep_rows)  # handled below by counting all cells
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    bg = max(counts, key=counts.get)

    # Extract the colored pattern from the panel containing the most non-background cells.
    best = []
    for r0, r1 in bands:
        for c0, c1 in panels:
            marks = [(r - r0, c - c0, grid[r][c])
